cypress_script:
describe('Login Form', () => {
  it('Successful login', () => {
    cy.visit('https://practicesoftwaretesting.com/auth/login');
    cy.get('input[id="email"]').type('user@example.com');
    cy.get('input[id="password"]').type('correctpassword');
    cy.get('input[data-test="login-submit"]').click();
    cy.url().should('eq', 'https://practicesoftwaretesting.com/');
  });
  it('Unsuccessful login', () => {
    cy.visit('https://practicesoftwaretesting.com/auth/login');
    cy.get('input[id="email"]').type('user@example.com');
    cy.get('input[id="password"]').type('wrongpassword');
    cy.get('input[data-test="login-submit"]').click();
    cy.url().should('eq', 'https://practicesoftwaretesting.com/auth/login');
  });
});

playwright_script:
import { test } from '@playwright/test';

 test.describe('Login Form', () => {
   test('Successful login', async ({ page }) => {
     await page.goto('https://practicesoftwaretesting.com/auth/login');
     await page.fill('input[id="email"]', 'user@example.com');
     await page.fill('input[id="password"]', 'correctpassword');
     await page.click('input[data-test="login-submit"]');
     await page.waitForURL('https://practicesoftwaretesting.com/');
   });

   test('Unsuccessful login', async ({ page }) => {
     await page.goto('https://practicesoftwaretesting.com/auth/login');
     await page.fill('input[id="email"]', 'user@example.com');
     await page.fill('input[id="password"]', 'wrongpassword');
     await page.click('input[data-test="login-submit"]');
     await page.waitForURL('https://practicesoftwaretesting.com/auth/login');
   });
 });
